import json
import math
import statistics

dates = ["2024-01-02", "2024-01-03", "2024-01-04", "2024-01-05", "2024-01-08", "2024-01-09"]
closes = {
    "AAA": [100.0, 102.0, 101.0, 104.0, 103.0, 106.0],
    "BBB": [50.0, 49.0, 51.0, 50.5, 52.0, 51.0],
}
prices = {"dates": dates, "tickers": ["AAA", "BBB"], "closes": closes}
rets = {t: [math.log(c[i] / c[i - 1]) for i in range(1, len(c))] for t, c in closes.items()}
returns = {"base_date": dates[0], "dates": dates[1:], "tickers": ["AAA", "BBB"], "values": rets}
w = 2
vol = {
    t: [None if i < w else statistics.stdev(r[i - w : i]) * math.sqrt(252) for i in range(len(r))]
    for t, r in rets.items()
}
volseries = {"returns": returns, "window": w, "annualized": True, "values": vol}
r = rets["AAA"]
ann_ret = 252 * statistics.mean(r)
ann_vol = math.sqrt(252) * statistics.stdev(r)
summary = {
    "ticker": "AAA",
    "ann_return": ann_ret,
    "ann_vol": ann_vol,
    "sharpe": ann_ret / ann_vol,
    "last_vol": vol["AAA"][-1],
}


def dd(t, values):
    wealth, peak, peak_d = 1.0, 1.0, dates[0]
    best = (0.0, dates[0], dates[0])
    for d, x in zip(dates[1:], values, strict=True):
        wealth *= math.exp(x)
        if wealth > peak:
            peak, peak_d = wealth, d
        depth = wealth / peak - 1
        if depth < best[0]:
            best = (depth, peak_d, d)
    return {"ticker": t, "depth": best[0], "peak_date": best[1], "trough_date": best[2]}


print(json.dumps({"prices": prices, "returns": returns, "vol": volseries, "summary": summary,
                  "dd": [dd(t, v) for t, v in rets.items()]}, indent=2))

